// In-memory state mutated before the log append that should make it durable
fn update_state(state: &mut State, log: &mut File, key: &str, val: &str) -> io::Result<()> {
    state.insert(key.to_string(), val.to_string());
    writeln!(log, "{key}={val}")?; // may fail; memory already changed
    Ok(())
}

// Data page overwritten on disk before the WAL record is written and synced
fn update_page(page_file: &mut File, wal: &mut File, off: u64, data: &[u8], rec: &[u8]) -> io::Result<()> {
    page_file.seek(SeekFrom::Start(off))?;
    page_file.write_all(data)?;
    wal.write_all(rec)?;
    wal.sync_all()?;
    Ok(())
}
```

fix:
Append and sync the log record first; apply the change to memory or pages only after the log write succeeds.
```rust
fn update_state(state: &mut State, log: &mut File, key: &str, val: &str) -> io::Result<()> {
    writeln!(log, "{key}={val}")?;
    log.sync_data()?;
    state.insert(key.to_string(), val.to_string());
    Ok(())
}
```
